def ini_section(s):
    result = {}
    for line in s.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' in line:
            key, value = line.split('=', 1)
            key = key.strip()
            value = value.strip()
            if key in result:
                raise ValueError(f"Duplicate key {key}")
            result[key] = value
    return result
